pre.script:
ht.request.headers.set("Content-Type", "application/json");
ht.request.body.set(JSON.stringify({
  title: "Runner Test",
  body: "Created by runner",
  userId: 1
}));

post.script:
const data = ht.response.json();
ht.environment.set("postId", String(data.id));
ht.environment.set("lastStatus", String(ht.response.status));

ht.test("Status is 201", () => {
  ht.expect(ht.response.status).toBe(201);
});
ht.test("Has id", () => {
  ht.expect(data.id).toBeTruthy();
});

const data = ht.response.json();
ht.environment.set("postId", "1");

ht.test("postId variable was chained", () => {
  ht.expect(ht.environment.get("lastStatus")).toBe("201");
});

const data = ht.response.json();
ht.environment.set("commentEmail", data[0].email);

ht.test("Status is 200", () => {
  ht.expect(ht.response.status).toBe(200);
});
ht.test("Has comments", () => {
  ht.expect(data.length).toBeGreaterThan(0);
});
ht.test("Comment has email", () => {
  ht.expect(data[0].email).toBeTruthy();
});

pre.script:
ht.request.headers.set("Content-Type", "application/json");
ht.request.body.set(JSON.stringify({
  id: parseInt(ht.environment.get("postId")),
  title: "Updated by Runner",
  body: "Modified in iteration",
  userId: 1
}));

post.script:
const data = ht.response.json();

ht.test("Status is 200", () => {
  ht.expect(ht.response.status).toBe(200);
});
ht.test("Title was updated", () => {
  ht.expect(data.title).toBe("Updated by Runner");
});
ht.test("Chained email from ep3", () => {
  ht.expect(ht.environment.get("commentEmail")).toBeTruthy();
});

ht.test("Status is 200", () => {
  ht.expect(ht.response.status).toBe(200);
});
ht.test("All chained vars present", () => {
  ht.expect(ht.environment.get("postId")).toBe("1");
  ht.expect(ht.environment.get("lastStatus")).toBe("201");
  ht.expect(ht.environment.get("commentEmail")).toBeTruthy();
});
